import { useState, useEffect } from 'react';

// ── Clock hook ───────────────────────────────────────────────
function useClock() {
  const [clock, setClock] = useState({ time: '', date: '' });
  useEffect(() => {
    const tick = () => {
      const now = new Date();
      setClock({
        time: now.toLocaleTimeString('id-ID', { hour12: false }),
        date: now.toLocaleDateString('id-ID', {
          weekday: 'short', day: '2-digit', month: 'short', year: 'numeric',
        }),
      });
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, []);
  return clock;
}

// ── Shield SVG icon ─────────────────────────────────────────
function ShieldIcon() {
  return (
    <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="var(--accent)" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/>
      <path d="M9 12l2 2 4-4" stroke="var(--cyan)" strokeWidth="1.6"/>
    </svg>
  );
}

export default function Navbar({ isRunning, alertCount, newCount }) {
  const { time, date } = useClock();

  const pillClass = isRunning
    ? alertCount > 0 ? 'pill-red' : 'pill-green'
    : 'pill-yellow';

  const pillLabel = isRunning
    ? alertCount > 0 ? `${alertCount} ALERT AKTIF` : 'MONITORING AKTIF'
    : 'SISTEM STANDBY';

  const dotClass = isRunning
    ? alertCount > 0 ? 'dot dot-red dot-pulse' : 'dot dot-green dot-pulse'
    : 'dot dot-yellow';

  return (
    <nav style={{
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      padding: '12px 22px',
      background: 'rgba(2, 11, 24, 0.96)',
      borderBottom: '1px solid var(--border)',
      backdropFilter: 'blur(20px)',
      position: 'sticky',
      top: 0,
      zIndex: 200,
    }}>

      {/* Brand */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 13 }}>
        <div style={{
          width: 42, height: 42,
          background: 'linear-gradient(135deg, #002a52, #004d8a)',
          border: '1px solid var(--border-md)',
          borderRadius: 10,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          boxShadow: '0 0 18px rgba(0,194,255,0.22)',
        }}>
          <ShieldIcon />
        </div>

        <div>
          <div style={{
            fontFamily: 'var(--font-display)',
            fontSize: 14,
            fontWeight: 700,
            color: 'var(--text-1)',
            letterSpacing: '1.5px',
            lineHeight: 1.1,
          }}>
            PIK CCTV
            <span style={{ color: 'var(--accent)', marginLeft: 8 }}>·</span>
            <span style={{ color: 'var(--accent)', marginLeft: 8 }}>Criminal Vehicle Detector</span>
          </div>
          <div style={{
            fontFamily: 'var(--font-mono)',
            fontSize: 9,
            color: 'var(--text-3)',
            letterSpacing: '2.5px',
            marginTop: 2,
          }}>
            AI-POWERED SURVEILLANCE · v2.4.1
          </div>
        </div>
      </div>

      {/* Right meta */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 18 }}>

        {/* Clock */}
        <div style={{ textAlign: 'right' }}>
          <div style={{
            fontFamily: 'var(--font-mono)',
            fontSize: 18,
            color: 'var(--cyan)',
            letterSpacing: '2px',
            lineHeight: 1,
          }}>
            {time}
          </div>
          <div style={{
            fontFamily: 'var(--font-mono)',
            fontSize: 8.5,
            color: 'var(--text-3)',
            letterSpacing: '1.5px',
            marginTop: 2,
          }}>
            {date}
          </div>
        </div>

        {/* Status pill */}
        <div className={`status-pill ${pillClass}`}>
          <span className={dotClass} />
          {pillLabel}
        </div>

        {/* New-alert badge */}
        {newCount > 0 && (
          <div className="animate-slide-top" style={{
            background: 'var(--red)',
            color: '#fff',
            borderRadius: 20,
            padding: '3px 9px',
            fontFamily: 'var(--font-display)',
            fontSize: 8,
            fontWeight: 700,
            letterSpacing: '1.5px',
            boxShadow: '0 0 14px rgba(255,45,85,0.55)',
          }}>
            {newCount} BARU
          </div>
        )}

        {/* Avatar / operator icon */}
        <div style={{
          width: 34, height: 34,
          borderRadius: 8,
          background: 'rgba(0,194,255,0.07)',
          border: '1px solid var(--border-md)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          cursor: 'pointer',
          transition: 'background 0.2s',
        }}>
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="var(--accent)" strokeWidth="2" strokeLinecap="round">
            <circle cx="12" cy="8" r="4"/>
            <path d="M4 20c0-4 3.6-7 8-7s8 3 8 7"/>
          </svg>
        </div>
      </div>
    </nav>
  );
}
